                    "$ref": "#/definitions/TimingPlanType"
                },
                "id": {
                    "type": "integer"
                },
                "adaptive": {
                    "type": "string",
                    "enum": [
                        "PLAN",
                        "PATTERN",
                        "STANDBY"
                    ]
                },
                "adaPlan": {
                    "type": "integer"
                },
                "adaMode": {
                    "type": "string",
                    "enum": [
                        "FREE",
                        "FLASH"
                    ]
                },
                "adaPattern": {
                    "type": "integer"
                },
                "tod": {
                    "type": "string",
                    "enum": [
                        "PLAN",
                        "PATTERN",
                        "STANDBY"
                    ]
                },
                "todPlan": {
                    "type": "integer"
                },
                "todMode": {
                    "type": "string",
                    "enum": [
                        "FREE",
                        "FLASH"
                    ]
                },
                "todPattern": {
                    "type": "integer"
                },
                "todnum": {
                    "type": "integer"
                },
                "override": {
                    "type": "string",
                    "enum": [
                        "PLAN",
                        "PATTERN",
                        "STANDBY"
                    ]
                },
                "ovrPlan": {
                    "type": "integer"
                },
                "ovrMode": {
                    "type": "string",
                    "enum": [
                        "FREE",
                        "FLASH"
                    ]
                },
                "ovrPattern": {
                    "type": "integer"
                },
                "now": {
                    "type": "string",
                    "enum": [
                        "PATTERN",
                        "FLASH",
                        "TBC",
                        "STANDBY",
                        "FAIL",
                        "PLAN",
                        "UNKNOWN"
                    ]
                },
                "op": {
                    "type": "string",
                    "enum": [
                        "PICKUP",
                        "OFFSET",
                        "NCS",
                        "TRANSITION"
                    ]
                },
                "to": {
